def simP(p,d,dt=0.002):
  Kp,Tp,Tw=np.abs(p)
  th=np.unwrap(d.bus_angle_rad.values);th=th-th[0]
  w=(th-lag(th,Tw,dt))/Tw/(2*np.pi*60)
  return d.active_power_pu.values[0]+lag(-Kp*w,Tp,dt)
